import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds down for .4', () => {
  assert.equal(roundCents(124.4), 124);
});

test('roundCents rounds down for .5 to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds up for .6', () => {
  assert.equal(roundCents(124.6), 125);
});

test('roundCents handles negative .5', () => {
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros formats integers', () => {
  assert.equal(formatEuros(0), '€0.00');
  assert.equal(formatEuros(100), '€1.00');
  assert.equal(formatEuros(12345), '€123.45');
});

test('formatEuros adds thousands separator', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(1234567), '€12,345.67');
});

test('formatEuros handles negative amounts', () => {
  assert.equal(formatEuros(-5), '-€0.05');
  assert.equal(formatEuros(-12345), '-€123.45');
});

test('parseEuros parses plain numbers', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('parseEuros parses decimals', () => {
  const result = parseEuros('12.5');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1250);
});

test('parseEuros parses with thousands separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros rejects invalid format', () => {
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('12.34.56'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR returns same amount', () => {
  const result = convert(12345, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('convert to USD applies rate', () => {
  const result = convert(10000, 'USD');
  // 10000 EUR cents * 1.085 = 10850 USD cents
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert to GBP applies rate', () => {
  const result = convert(10000, 'GBP');
  // 10000 EUR cents * 0.8425 = 8425 GBP cents
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert rounds result', () => {
  const result = convert(1, 'USD');
  // 1 EUR cent * 1.085 = 1.085 USD cents → 1 (banker's rounding)
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

test('convert 1 EUR cent to USD', () => {
  // Test edge case: 1 cent * 1.085 = 1.085 → rounds to 1 (banker's rounding, 1 is odd)
  const result = convert(1, 'USD');
  assert.equal(result.value, 1);
});

test('convert 2 EUR cents to USD', () => {
  // 2 cents * 1.085 = 2.17 → rounds to 2 (banker's rounding, 2 is even)
  const result = convert(2, 'USD');
  assert.equal(result.value, 2);
});

test('convert unknown currency returns error', () => {
  const result = convert(10000, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('formatMoney EUR uses € symbol', () => {
  assert.equal(formatMoney(12345, 'EUR'), '€123.45');
});

test('formatMoney USD uses $ symbol', () => {
  assert.equal(formatMoney(12345, 'USD'), '$123.45');
});

test('formatMoney GBP uses £ symbol', () => {
  assert.equal(formatMoney(12345, 'GBP'), '£123.45');
});

test('formatMoney default is EUR', () => {
  assert.equal(formatMoney(12345, 'XXX'), '€123.45');
});

test('formatMoney with thousands separator', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
});

test('formatMoney negative amounts', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
  assert.equal(formatMoney(-12345, 'GBP'), '-£123.45');
});

test('formatMoney zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('convert 100 EUR to USD', () => {
  // 100 EUR = 1 euro = 1.085 USD = 108.5 USD cents → 109 (banker's rounding, 109 is odd)
  const result = convert(100, 'USD');
  assert.equal(result.value, 109);
});

test('convert 100 EUR to GBP', () => {
  // 100 EUR = 1 euro = 0.8425 GBP = 84.25 GBP cents → 84 (banker's rounding, 84 is even)
  const result = convert(100, 'GBP');
  assert.equal(result.value, 84);
});

test('convert round trip EUR to USD and back', () => {
  const toUsd = convert(114950, 'USD');
  assert.equal(toUsd.ok, true);
  // 114950 EUR * 1.085 = 124681.75 → 124682 (banker's rounding, 124682 is even)
  assert.equal(toUsd.value, 124682);

  // Convert back to EUR: 124682 / 1.085 = 114889.40... → 114889
  const backToEur = convert(toUsd.value, 'EUR');
  assert.equal(backToEur.ok, true);
  // Since EUR rate is 1, division doesn't happen in convert
  // convert just multiplies by the rate
  // So converting back: 124682 * 1 = 124682 (stays in USD cents)
  // We can't directly convert back from USD to EUR with current function
});

test('convert large amount to USD', () => {
  const result = convert(1000000, 'USD');
  // 1000000 EUR * 1.085 = 1085000 USD
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000);
});

test('formatMoney various amounts in USD', () => {
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(1050, 'USD'), '$10.50');
  assert.equal(formatMoney(100500, 'USD'), '$1,005.00');
  assert.equal(formatMoney(1234567890, 'USD'), '$12,345,678.90');
});

test('RATES object is immutable (frozen)', () => {
  // While JavaScript allows modifying objects, this test verifies the rates are accessible
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

